import java.io.File;
import java.nio.file.*;
import java.util.*;
import org.kanger.*;
import org.kanger.ContextDependentCutInspection.*;
import org.kanger.ContextDependentCandidateInspection.*;
import org.kanger.ContextDependentCandidateInspection.Request;
import org.kanger.ContextDependentCandidateInspection.Result;
