public final class ContextDependentCandidateRunner {
    private static int checks;
    private interface Attempt{void run()throws Exception;}
    private static void require(boolean b,String why){checks++;if(!b)throw new AssertionError(why);}
    private static void reject(Attempt a,String why)throws Exception{boolean no=false;try{a.run();}catch(Exception expected){no=true;}require(no,why);}
    private static Mind memory()throws Exception{User u=new User();Mind m=new Mind(u);u.setCurrentMind(m);return m;}
    private static Rule raw(Mind m,String text)throws Exception{return (Rule)m.compileLine(text,false,new LinkedList<ITerm>());}
    private static Policy policy(){return new Policy(2000000,1000,1000,64000000,200000);}
    private static Request request(int rounds,String... statements){return new Request(new ContextDependentIterationInspection.Request(policy(),10000,rounds),Arrays.asList(statements));}
    private static Member member(Mind m,int id,boolean x)throws Exception{return new Member(m,ContextProductionInventory.inspect(m,new UUID(0,id),3,x,Collections.emptyList(),1000));}
    private static Source source(Member m,long rule){return new Source(m.inventory.context,m.inventory.revision,rule,m.inventory.localX,"inventory:"+m.inventory.fingerprint);}
    private static void incomplete(Result r,String phase,String why){require(r.verdict==Verdict.INCOMPLETE&&r.phase.equals(phase),why+" actual="+r.verdict+"/"+r.phase+"/"+r.reason);require(r.base==null&&r.proposed==null&&r.candidates.isEmpty()&&r.originals.isEmpty()&&r.oppositions.isEmpty()&&r.baseFingerprint==null&&r.proposedFingerprint==null,"incomplete append cannot expose an accepted manifest or iteration prefix");}
    private static void stableAndBatch()throws Exception{
        Mind parent=memory();Rule seed=raw(parent,"!seed(1);");Member base=member(parent,1,true);Mind child=new Mind(parent);Rule hp=raw(child,"!@x seed(x)->p(x);"),hq=raw(child,"!@x p(x)->q(x);");Member proposed=member(child,1,true);String before=proposed.inventory.fingerprint;int terms=child.getTerms().size();Request req=request(10,hp.getOrigin(),hq.getOrigin());Result r=ContextDependentCandidateInspection.inspect(base,proposed,Collections.emptyList(),req);require(r.verdict==Verdict.STABLE_PENDING&&r.base.status==ContextDependentIterationInspection.Status.FIXED_POINT&&r.proposed.status==ContextDependentIterationInspection.Status.FIXED_POINT,"actual native batch append has checked base and proposed closures");require(r.candidates.size()==2&&r.originals.size()==3,"whole candidate batch and all preserved originals mapped");require(!source(base,seed.getId()).equals(source(proposed,seed.getId()))&&r.originals.get(source(proposed,seed.getId())).equals(source(base,seed.getId())),"whole-view fingerprint rebasing is explicit, not mistaken for a new original");for(Source s:r.candidates)require(r.originals.get(s).equals(s),"each actual added Source keeps its own new identity");require(r.proposed.frontier.common.stream().anyMatch(row->row.predicate.equals("q")&&row.sources.containsAll(r.candidates)),"final q proof depends on both incoming statements");require(before.equals(ContextProductionInventory.inspect(child,proposed.inventory.context,3,true,Collections.emptyList(),1000).fingerprint)&&terms==child.getTerms().size(),"append inspection does not allocate native product Terms or write child");require(base.inventory.fingerprint.equals(ContextProductionInventory.inspect(parent,base.inventory.context,3,true,Collections.emptyList(),1000).fingerprint),"parent unchanged");require(r.oppositions.isEmpty()&&r.reason.contains("admission unknown"),"stable pending is diagnostic, not admission");reject(()->r.originals.clear(),"rebasing immutable");reject(()->r.candidates.clear(),"candidate set immutable");reject(()->req.statements.clear(),"exact batch request immutable");
        incomplete(ContextDependentCandidateInspection.inspect(base,proposed,Collections.emptyList(),request(10,hq.getOrigin(),hp.getOrigin())),"native-append-manifest","candidate order bound to actual native append");incomplete(ContextDependentCandidateInspection.inspect(base,proposed,Collections.emptyList(),request(10,hp.getOrigin())),"native-append-manifest","extra unaccounted primary row refused");incomplete(ContextDependentCandidateInspection.inspect(base,proposed,Collections.emptyList(),request(10,"!different(1);",hq.getOrigin())),"native-append-manifest","wrong incoming text refused even with matching row count");incomplete(ContextDependentCandidateInspection.inspect(base,proposed,Collections.emptyList(),request(1,hp.getOrigin(),hq.getOrigin())),"proposed-iteration","completed base cannot promote an incomplete proposed cycle");
        raw(child,"!changed(1);");reject(()->ContextDependentCandidateInspection.inspect(base,proposed,Collections.emptyList(),req),"stale actual child throws outside incomplete conversion");parent.release(child);
    }
    private static void collisionAndBase()throws Exception{
        Mind xm=memory(),am=memory(),bm=memory();raw(xm,"!anchor(1);");raw(am,"!left(1);");raw(am,"!p(1);");raw(bm,"!right(1);");raw(bm,"!~p(1);");Member base=member(xm,21,true),a=member(am,22,false),b=member(bm,23,false);Mind child=new Mind(xm);Rule h=raw(child,"!@x left(x)&&right(x)->p(x);"),extra=raw(child,"!extra(1);");Member proposed=member(child,21,true);Cut ca=new Cut(null,Collections.singletonList(a)),cb=new Cut(null,Collections.singletonList(b));
        for(boolean reverse:new boolean[]{false,true}){Result r=ContextDependentCandidateInspection.inspect(base,proposed,reverse?Arrays.asList(cb,ca):Arrays.asList(ca,cb),request(5,h.getOrigin(),extra.getOrigin()));require(r.verdict==Verdict.CANDIDATE_REFUTED&&r.base.status==ContextDependentIterationInspection.Status.FIXED_POINT&&r.proposed.completedRounds==2,"new candidate causes second-pass receiving collision in either cut order");require(r.candidates.size()==2&&!r.oppositions.isEmpty(),"whole atomic batch retained with exact sourced opposition");for(Opposition o:r.oppositions){require(o.cut.equals(ca.key)&&o.candidates.equals(Collections.singleton(source(proposed,h.getId()))),"only incoming Horn statement is causal, unrelated batch assertion is not blamed");require(o.originalSources.size()==4&&o.originalSources.contains(source(proposed,h.getId())),"all four original causal Sources preserved");require(o.originalSources.stream().filter(s->!s.localX).count()==3,"duplicate native IDs from independent physical members remain separate Sources");}reject(()->r.oppositions.clear(),"opposition list immutable");}
        xm.release(child);
        Mind bad=memory();Rule p=raw(bad,"!p(1);"),np=raw(bad,"!~p(1);");Member old=member(bad,31,true);Mind next=new Mind(bad);Rule incoming=raw(next,"!q(1);");Member current=member(next,31,true);Result already=ContextDependentCandidateInspection.inspect(old,current,Collections.emptyList(),request(5,incoming.getOrigin()));require(already.verdict==Verdict.BASE_REFUTED&&already.base.completedRounds==0&&already.proposed==null,"pre-existing contradiction stops before evaluating proposed candidate");for(Opposition o:already.oppositions){require(o.candidates.isEmpty()&&o.originalSources.equals(new HashSet<>(Arrays.asList(source(old,p.getId()),source(old,np.getId())))),"pre-existing proof retains parent Sources and never blames new q");}bad.release(next);
        Mind growing=memory();raw(growing,"!seed(1);");raw(growing,"!@x seed(x)->p(x);");raw(growing,"!@x p(x)->q(x);");Member gb=member(growing,41,true);Mind gc=new Mind(growing);Rule unrelated=raw(gc,"!unrelated(1);");incomplete(ContextDependentCandidateInspection.inspect(gb,member(gc,41,true),Collections.emptyList(),request(1,unrelated.getOrigin())),"base-iteration","an incomplete base cannot be replaced by a proposed-only verdict");growing.release(gc);
    }
    private static void witnessRebasing()throws Exception{
        for(int width:new int[]{1,7,17,65}){Mind parent=memory();StringBuilder prefix=new StringBuilder(),args=new StringBuilder();for(int i=0;i<width;i++){prefix.append("@x").append(i).append(' ');if(i>0)args.append(',');args.append('x').append(i);}Rule seed=raw(parent,"!"+prefix+"$u rel("+args+",u);");Member base=member(parent,100+width,true);Mind child=new Mind(parent);Rule h=raw(child,"!"+prefix+"@u rel("+args+",u)->out("+args+",u);");Member proposed=member(child,100+width,true);int terms=child.getTerms().size();Result r=ContextDependentCandidateInspection.inspect(base,proposed,Collections.emptyList(),request(5,h.getOrigin()));require(r.verdict==Verdict.STABLE_PENDING,"dependent incoming native candidate qualifies diagnostically at rank "+width+" reason="+r.reason);ContextDependentProductionInspection.Row row=r.proposed.frontier.common.get(0);ContextDependentProductionInspection.TermView witness=row.arguments.get(width);require(witness.arguments.size()==width&&witness.symbolSource.equals(source(proposed,seed.getId()))&&r.originals.get(witness.symbolSource).equals(source(base,seed.getId())),"typed application remains child-qualified with exact explicit original rebasing");for(int i=0;i<width;i++)require(witness.arguments.get(i)==row.arguments.get(i),"native incoming qualification preserves dependency coordinate "+i);require(child.getTerms().size()==terms&&ContextProductionInventory.inspect(child,proposed.inventory.context,3,true,Collections.emptyList(),1000).generated.isEmpty(),"dependent products are not flattened into generated native scalar Cvars");parent.release(child);}
    }
    private static void malformedAndCancellation()throws Exception{
        Mind parent=memory();Rule seed=raw(parent,"!seed(1);");Member base=member(parent,201,true);Mind deleted=new Mind(parent);Rule h=raw(deleted,"!@x seed(x)->out(x);");seed.setDeleted(true,deleted);Member removed=member(deleted,201,true);incomplete(ContextDependentCandidateInspection.inspect(base,removed,Collections.emptyList(),request(5,h.getOrigin())),"native-append-manifest","native child deletion cannot masquerade as append-only change");parent.release(deleted);
        Mind wrong=memory();raw(wrong,"!seed(1);");Rule candidate=raw(wrong,"!new(1);");incomplete(ContextDependentCandidateInspection.inspect(base,member(wrong,201,true),Collections.emptyList(),request(5,candidate.getOrigin())),"native-append-manifest","equivalent independent Mind is not actual native child");
        Mind child=new Mind(parent);Rule unsupported=raw(child,"!@x a(x)->b(x)||c(x);");Member proposed=member(child,201,true);incomplete(ContextDependentCandidateInspection.inspect(base,proposed,Collections.emptyList(),request(5,unsupported.getOrigin())),"proposed-iteration","native append alone does not make unsupported proposed language stable");reject(()->new Request(new ContextDependentIterationInspection.Request(policy(),10000,5),Collections.emptyList()),"empty incoming batch refused");reject(()->request(5,"?p(1);"),"query is not incoming assertion");boolean interrupted=false;Thread.currentThread().interrupt();try{ContextDependentCandidateInspection.inspect(base,proposed,Collections.emptyList(),request(5,unsupported.getOrigin()));}catch(InterruptedException expected){interrupted=true;require(Thread.currentThread().isInterrupted(),"cancellation flag preserved");}finally{Thread.interrupted();}require(interrupted,"cancellation never yields a pending-candidate verdict");parent.release(child);
    }
    private static final class Fixture implements AutoCloseable{
        final User user=new User();final DB db=new DB();final Mind root;
        Fixture(Path d,String name)throws Exception{user.setDatabaseDir(d+File.separator);user.setUserDir(Files.createDirectories(d.resolve("operator")).toString());db.init(user);Mind m=new Mind(user);user.setCurrentMind(m);root=(Mind)m.useStorage(name);user.setCurrentMind(root);}
        @Override public void close()throws Exception{if(user.getCurrentMind().isStorageUsed())user.setCurrentMind(user.getCurrentMind().closeStorage());}
    }
    private static void owning()throws Exception{
        Path dir=Files.createTempDirectory("dependent-candidate-db-");try(Fixture a=new Fixture(dir,"A")){require(a.root.compile("!left(1); !p(1);",null,false),"A fixture");}try(Fixture b=new Fixture(dir,"B")){require(b.root.compile("!right(1); !~p(1);",null,false),"B fixture");}
        for(boolean reverse:new boolean[]{false,true})try(Fixture f=new Fixture(dir,"X"+reverse)){
            require(f.root.compile("!anchor(1);",null,false),"actual parent");f.db.connectContext(reverse?"B":"A");f.db.connectContext(reverse?"A":"B");long revision=f.db.getRevision();ContextProductionInventory pi=ContextProductionInventory.inspect(f.root,f.db.getContextId(),revision,true,Collections.emptyList(),1000);Mind child=new Mind(f.root);Rule h=raw(child,"!@x left(x)&&right(x)->p(x);"),extra=raw(child,"!extra(1);");ContextProductionInventory ci=ContextProductionInventory.inspect(child,f.db.getContextId(),revision,true,Collections.emptyList(),1000);
            try(ContextPendingProductionSnapshotSession lease=ContextPendingProductionSnapshotSession.open(f.db,child,1000)){
                int terms=child.getTerms().size();Result r=lease.inspectDependentCandidate(request(5,h.getOrigin(),extra.getOrigin()));require(r.verdict==Verdict.CANDIDATE_REFUTED&&r.proposed.completedRounds==2&&r.candidates.size()==2,"actual incoming native batch rejected diagnostically with exact second-round causality");require(r.baseFingerprint.equals(pi.fingerprint)&&r.proposedFingerprint.equals(ci.fingerprint),"actual lease supplies parent/child manifests, not caller replacement views");for(Opposition o:r.oppositions)require(o.candidates.size()==1&&o.candidates.iterator().next().rule==h.getId()&&o.originalSources.size()==4,"actual physical Source support attributes only the causal candidate");require(f.db.getRevision()==revision&&ci.fingerprint.equals(ContextProductionInventory.inspect(child,f.db.getContextId(),revision,true,Collections.emptyList(),1000).fingerprint)&&terms==child.getTerms().size(),"native candidate qualification never settles or writes products");incomplete(lease.inspectDependentCandidate(request(5,extra.getOrigin(),h.getOrigin())),"native-append-manifest","owning lease refuses wrong ordered incoming text");incomplete(lease.inspectDependentCandidate(request(1,h.getOrigin(),extra.getOrigin())),"proposed-iteration","owning incomplete run exposes no native accepted prefix");raw(child,"!changed(1);");reject(()->lease.inspectDependentCandidate(request(5,h.getOrigin(),extra.getOrigin())),"owning whole-child guard remains outside diagnostic incomplete conversion");
            }finally{f.root.release(child);}require(pi.fingerprint.equals(ContextProductionInventory.inspect(f.root,f.db.getContextId(),revision,true,Collections.emptyList(),1000).fingerprint),"actual parent unchanged after release");
        }
    }
    public static void main(String[] args){try{System.setProperty("user.home",Files.createTempDirectory("dependent-candidate-").toString());stableAndBatch();collisionAndBase();witnessRebasing();malformedAndCancellation();owning();System.out.println("CONTEXT_DEPENDENT_CANDIDATE_PASS checks="+checks);System.exit(0);}catch(Throwable t){t.printStackTrace();System.exit(1);}}
}
